import * as n1 from './solid-demo01';
import * as n2 from './solid-demo02';
import * as n3 from './solid-demo03';
import * as n4 from './solid-demo04';
import * as n5 from './solid-demo05';
import * as v1 from '../Virtualizer/solid-demo01';
import * as v2 from '../Virtualizer/solid-demo02';
import * as v3 from '../Virtualizer/solid-demo03';
import * as v4 from '../Virtualizer/solid-demo04';
import * as v5 from '../Virtualizer/solid-demo05';
import * as v6 from '../Virtualizer/solid-demo06';
import * as v7 from '../Virtualizer/solid-demo07';
const results: {title: string; error?: string}[] = [];
for (const demo of [n1,n2,n3,n4,n5,v1,v2,v3,v4,v5,v6,v7]) {
  const section=document.createElement('section');
  section.dataset.nativeModule=demo.title;
  const heading=document.createElement('h2'); heading.textContent=demo.title;
  const host=document.createElement('div');host.dataset.nativeSolidDemo='';
  section.append(heading,host);document.body.append(section);
  try { demo.mount(host);results.push({title:demo.title}); }
  catch(error) {host.dataset.demoError=String(error);results.push({title:demo.title,error:String(error)});}
}
Object.assign(window,{nativeQualification:results});
