import {AriaLabelingProps, DOMProps} from '@react-types/shared';
import {
  ClassNameOrFunction,
  ContextValue,
  dom,
  RenderProps,
  SlotProps,
  useContextProps,
  useRenderProps
} from './utils';
import {HoverProps, useHover} from 'react-aria/useHover';
import {mergeProps} from 'react-aria/mergeProps';
import {createContext, merge, omit} from 'solid-js';
import {useObjectRef, type Ref} from 'react-aria/private/utils/useObjectRef';
import {useSyncRef} from 'react-aria/private/utils/useSyncRef';
import type {JSX} from '@solidjs/web';
type HTMLAttributes<T> = JSX.HTMLAttributes<T>;
import {useFocusRing} from 'react-aria/useFocusRing';

export interface GroupRenderProps {
  /**
   * Whether the group is currently hovered with a mouse.
   *
   * @selector [data-hovered]
   */
  isHovered: boolean;
  /**
   * Whether an element within the group is focused, either via a mouse or keyboard.
   *
   * @selector [data-focus-within]
   */
  isFocusWithin: boolean;
  /**
   * Whether an element within the group is keyboard focused.
   *
   * @selector [data-focus-visible]
   */
  isFocusVisible: boolean;
  /**
   * Whether the group is disabled.
   *
   * @selector [data-disabled]
   */
  isDisabled: boolean;
  /**
   * Whether the group is invalid.
   *
   * @selector [data-invalid]
   */
  isInvalid: boolean;
}

export interface GroupProps
  extends
    AriaLabelingProps,
    Omit<
      HTMLAttributes<HTMLElement>,
      'children' | 'className' | 'style' | 'render' | 'role' | 'slot' | 'ref' | keyof AriaLabelingProps | keyof DOMProps
    >,
    DOMProps,
    HoverProps,
    RenderProps<GroupRenderProps>,
    SlotProps {
  /**
   * The CSS [className](https://developer.mozilla.org/en-US/docs/Web/API/Element/className) for the
   * element. A function may be provided to compute the class based on component state.
   *
   * @default 'react-aria-Group'
   */
  className?: ClassNameOrFunction<GroupRenderProps>;
  /** Whether the group is disabled. */
  isDisabled?: boolean;
  /** Whether the group is invalid. */
  isInvalid?: boolean;
  /** Whether the group is read only. */
  isReadOnly?: boolean;
  /**
   * An accessibility role for the group. By default, this is set to `'group'`.
   * Use `'region'` when the contents of the group is important enough to be
   * included in the page table of contents. Use `'presentation'` if the group
   * is visual only and does not represent a semantic grouping of controls.
   *
   * @default 'group'
   */
  role?: 'group' | 'region' | 'presentation';
}

export const GroupContext = createContext<ContextValue<GroupProps, HTMLDivElement>>({});

/**
 * A group represents a set of related UI controls, and supports interactive states for styling.
 */
export function Group(inputProps: GroupProps & {ref?: Ref<HTMLDivElement>}) {
  let localRef = useObjectRef<HTMLDivElement>();
  useSyncRef(inputProps, localRef);
  let [props, ref] = useContextProps(inputProps, localRef, GroupContext);
  let otherProps = omit(props, 'isDisabled', 'isInvalid', 'isReadOnly', 'onHoverStart', 'onHoverChange', 'onHoverEnd', 'ref');
  let isDisabled = () => props.isDisabled ?? (!!props['aria-disabled'] && props['aria-disabled'] !== 'false');
  let isInvalid = () => props.isInvalid ?? (!!props['aria-invalid'] && props['aria-invalid'] !== 'false');

  let {hoverProps, isHovered} = useHover(merge(props, {get isDisabled() { return isDisabled(); }}));
  let {isFocused, isFocusVisible, focusProps} = useFocusRing({
    within: true
  });

  let renderProps = useRenderProps(merge(props, {
    values: {
      get isHovered() { return isHovered(); },
      get isFocusWithin() { return isFocused(); },
      get isFocusVisible() { return isFocusVisible(); },
      get isDisabled() { return isDisabled(); },
      get isInvalid() { return isInvalid(); }
    },
    defaultClassName: 'react-aria-Group'
  }));

  return (
    <dom.div
      {...mergeProps(otherProps, focusProps, hoverProps)}
      {...renderProps}
      ref={ref}
      role={props.role ?? 'group'}
      slot={props.slot ?? undefined}
      data-focus-within={isFocused() ? 'true' : undefined}
      data-hovered={isHovered() ? 'true' : undefined}
      data-focus-visible={isFocusVisible() ? 'true' : undefined}
      data-disabled={isDisabled() ? 'true' : undefined}
      data-invalid={isInvalid() ? 'true' : undefined}
      data-readonly={props.isReadOnly ? 'true' : undefined}>
      {renderProps.children}
    </dom.div>
  );
}
