import {useLocale} from './I18nProvider';
import {createMemo} from 'solid-js';

let cache = new Map<string, Intl.Collator>();

/**
 * Provides localized string collation for the current locale. Automatically updates when the locale
 * changes, and handles caching of the collator for performance.
 *
 * @param options - Collator options.
 */
export function useCollator(options?: Intl.CollatorOptions): Intl.Collator {
  let localeInfo = useLocale();
  let collator = createMemo(() => {
    let locale = localeInfo.locale;
    let cacheKey =
      locale +
      (options
        ? Object.entries(options)
            .sort((a, b) => (a[0] < b[0] ? -1 : 1))
            .join()
        : '');
    if (cache.has(cacheKey)) {
      return cache.get(cacheKey)!;
    }

    let formatter = new Intl.Collator(locale, options);
    cache.set(cacheKey, formatter);
    return formatter;
  });

  // Keep the public Intl methods stable while resolving the current locale and
  // options in the caller's tracking scope or event, not during component setup.
  return {
    compare: (a, b) => collator().compare(a, b),
    resolvedOptions: () => collator().resolvedOptions()
  };
}
