import {ContextValue, dom, DOMProps, DOMRenderProps, useContextProps} from './utils';
import {FormValidationContext} from 'react-stately/private/form/useFormValidationState';
import {GlobalDOMAttributes, FormProps as SharedFormProps} from '@react-types/shared';
import {createContext, merge, omit, untrack, type Ref} from 'solid-js';

export interface FormProps
  extends
    SharedFormProps,
    DOMProps,
    DOMRenderProps<'form', undefined>,
    GlobalDOMAttributes<HTMLFormElement> {
  /**
   * The CSS [className](https://developer.mozilla.org/en-US/docs/Web/API/Element/className) for the
   * element.
   *
   * @default 'react-aria-Form'
   */
  className?: string;
  /**
   * Whether to use native HTML form validation to prevent form submission
   * when a field value is missing or invalid, or mark fields as required
   * or invalid via ARIA.
   *
   * @default 'native'
   */
  validationBehavior?: 'aria' | 'native';
}

export const FormContext = createContext<ContextValue<FormProps, HTMLFormElement>>(null);

/**
 * A form is a group of inputs that allows users to submit data to a server,
 * with support for providing field validation errors.
 */
export function Form(props: FormProps & {ref?: Ref<HTMLFormElement>}) {
  let ref = untrack(() => props.ref);
  [props, ref] = useContextProps(props, ref, FormContext);
  let domProps = merge(omit(props, 'validationErrors', 'validationBehavior', 'children', 'className', 'ref', 'onInvalid'), {
    // Native invalid events do not bubble. Use the existing capture bridge so
    // the source form callback can cancel the field's automatic focus.
    get onInvalidCapture() {return props.onInvalid;}
  });
  let context = merge(props, {get validationBehavior() {return props.validationBehavior ?? 'native';}});
  let validationErrors = merge(() => props.validationErrors ?? {});
  return (
    <dom.form
      novalidate={context.validationBehavior !== 'native'}
      {...domProps}
      ref={ref}
      className={props.className || 'react-aria-Form'}>
      <FormContext value={context}>
        <FormValidationContext value={validationErrors}>
          {props.children}
        </FormValidationContext>
      </FormContext>
    </dom.form>
  );
}
