import {Collection, CollectionStateBase, Node} from '@react-types/shared';
import {CollectionBuilder} from './CollectionBuilder';
import {createMemo, type Accessor, type Element} from 'solid-js';

interface CollectionOptions<T, C extends Collection<Node<T>>> extends Omit<
  CollectionStateBase<T, C>,
  'children'
> {
  children?:
    | Element
    | null
    | Element[]
    | ((item: T) => Element);
}

type CollectionFactory<T, C extends Collection<Node<T>>> = (node: Iterable<Node<T>>) => C;

export function useCollection<T, C extends Collection<Node<T>> = Collection<Node<T>>>(
  props: CollectionOptions<T, C>,
  factory: CollectionFactory<T, C>,
  context?: unknown
): Accessor<C> {
  let builder = new CollectionBuilder<any>();
  return createMemo(() => {
    if (props.collection) {
      return props.collection;
    }
    let nodes = builder.build({children: props.children, items: props.items}, context);
    return factory(nodes);
  });
}

// Keep a stable native handle while source-derived class instances update.
// Methods have stable identity and dispatch against the current own receiver.
const liveViewReaders = new WeakMap<object, Accessor<object>>();

/** Reads the immutable source image when a native consumer compares identity. */
export function readLiveView<C extends object>(view: C): C {
  return (liveViewReaders.get(view)?.() ?? view) as C;
}

export function liveView<C extends object>(read: Accessor<C>): C {
  let methods = new Map<PropertyKey, (...args: any[]) => any>();
  let view = new Proxy({} as C, {
    get(_target, key) {
      let current = read();
      let value = Reflect.get(current, key, current);
      if (typeof value !== 'function') {
        return value;
      }
      if (!methods.has(key)) {
        methods.set(key, (...args) => {
          let current = read();
          return Reflect.apply(Reflect.get(current, key, current) as (...args: any[]) => any, current, args);
        });
      }
      return methods.get(key);
    },
    has(_target, key) {return key in read();}
  });
  liveViewReaders.set(view, read);
  return view;
}
