import {DOMAttributes, FocusableElement, RefObject} from '@react-types/shared';
import {getColumnHeaderId} from './utils';
import {GridNode} from 'react-stately/private/grid/GridCollection';
import intlMessages from '../../intl/table/*.json';
import {isAndroid} from '../utils/platform';
import {mergeProps} from '../utils/mergeProps';
import {TableState} from 'react-stately/useTableState';
import {useDescription} from '../utils/useDescription';
import {Accessor, createEffect, createMemo, merge, untrack} from 'solid-js';
import {useFocusable} from '../interactions/useFocusable';
import {useGridCell} from '../grid/useGridCell';
import {useLocalizedStringFormatter} from '../i18n/useLocalizedStringFormatter';
import {usePress} from '../interactions/usePress';

export interface AriaTableColumnHeaderProps<T> {
  /**
   * An object representing the [column header](https://www.w3.org/TR/wai-aria-1.1/#columnheader).
   * Contains all the relevant information that makes up the column header.
   */
  node: GridNode<T>;
  /**
   * Whether the [column header](https://www.w3.org/TR/wai-aria-1.1/#columnheader) is contained in a
   * virtual scroller.
   */
  isVirtualized?: boolean;
  /**
   * Whether the column header or its first focusable child element should be focused when the
   * column header is focused. Defaults to 'child' in arrow keyboard navigation mode and 'cell' in
   * tab keyboard navigation mode.
   */
  focusMode?: 'child' | 'cell';
  /**
   * Whether the column header should support arrow key navigation even when the containing table
   * uses tab keyboard navigation. Allows users to navigate between columns with arrow keys while
   * focus is on an interactive child element within the cell.
   */
  allowsArrowNavigation?: boolean;
}

export interface TableColumnHeaderAria {
  /** Props for the [column header](https://www.w3.org/TR/wai-aria-1.1/#columnheader) element. */
  columnHeaderProps: DOMAttributes;
  /** Whether the column is currently in a pressed state. */
  isPressed: Accessor<boolean>;
}

/**
 * Provides the behavior and accessibility implementation for a column header in a table.
 *
 * @param props - Props for the column header.
 * @param state - State of the table, as returned by `useTableState`.
 * @param ref - The ref attached to the column header element.
 */
export function useTableColumnHeader<T>(
  props: AriaTableColumnHeaderProps<T>,
  state: TableState<T>,
  ref: RefObject<FocusableElement | null>
): TableColumnHeaderAria {
  let node = merge(() => props.node);
  let allowsSorting = () => node.props.allowsSorting;
  let {gridCellProps} = useGridCell(merge({focusMode: 'child' as const}, props), state, ref);

  let isSelectionCellDisabled = () =>
    node.props.isSelectionCell && state.selectionManager.selectionMode === 'single';

  let {pressProps, isPressed} = usePress({
    get isDisabled() { return !allowsSorting() || isSelectionCellDisabled(); },
    onPress() {
      state.sort(node.key);
    },
    ref
  });

  // Needed to pick up the focusable context, enabling things like Tooltips for example
  let {focusableProps} = useFocusable({}, ref);

  let isSortedColumn = () => state.sortDescriptor?.column === node.key;
  let sortDirection = () => state.sortDescriptor?.direction;
  // aria-sort not supported in Android Talkback
  let ariaSort = (): DOMAttributes['aria-sort'] => node.props.allowsSorting && !isAndroid()
    ? isSortedColumn() ? sortDirection() : 'none' : undefined;

  let stringFormatter = useLocalizedStringFormatter(intlMessages, '@react-aria/table');
  let sortDescription = () => {
  let description;
  if (allowsSorting()) {
    description = `${stringFormatter.format('sortable')}`;
    // Android Talkback doesn't support aria-sort so we add sort order details to the aria-described by here
    if (isSortedColumn() && sortDirection() && isAndroid()) {
      description = `${description}, ${stringFormatter.format(sortDirection()!)}`;
    }
  }
  return description;
  };

  let descriptionProps = useDescription(sortDescription);

  let shouldDisableFocus = () => state.collection.size === 0;
  let disabledFocusPolicy = createMemo<{disabled: boolean; manager: TableState<T>['selectionManager']; key: typeof node.key}>(previous => {
    let policy = {disabled: shouldDisableFocus(), manager: state.selectionManager, key: node.key};
    return previous && previous.disabled === policy.disabled &&
      previous.manager === policy.manager && previous.key === policy.key ? previous : policy;
  });
  createEffect(disabledFocusPolicy, ({disabled, manager, key}) => {
    // Source samples current focus when the empty-table policy changes; focus
    // itself is not a dependency of this correction.
    if (disabled && untrack(() => manager.focusedKey) === key) {
      untrack(() => manager.setFocusedKey(null));
    }
  });

  return {
    columnHeaderProps: merge(mergeProps(
        focusableProps,
        gridCellProps,
        pressProps,
        descriptionProps,
        // If the table is empty, make all column headers untabbable
        merge(() => shouldDisableFocus() ? {tabIndex: -1} : {})
      ), {
      role: 'columnheader' as const,
      get id() { return getColumnHeaderId(state, node.key); },
      get 'aria-colspan'() { return node.colSpan && node.colSpan > 1 ? node.colSpan : undefined; },
      get 'aria-sort'() { return ariaSort(); }
    }),
    isPressed
  };
}
